-- 2. Biathlon Explained: Skiing Meets Shooting
-- ============================================================================
INSERT INTO articles (
    slug, title, excerpt, content, category, sport_code,
    meta_description, status, published_at, source_type
) VALUES (
    'biathlon-explained-skiing-meets-shooting',

    '{
        "en": "Biathlon Explained: Skiing Meets Shooting",
        "de": "Biathlon erklärt: Wenn Skifahren auf Schießen trifft",
        "fr": "Le Biathlon Expliqué : Ski et Tir",
        "it": "Biathlon Spiegato: Sci e Tiro",
        "es": "Biatlón Explicado: Esquí y Tiro",
        "pt": "Biatlo Explicado: Esqui e Tiro",
        "nl": "Biathlon Uitgelegd: Skiën en Schieten",
        "ar": "شرح البياثلون: التزلج يلتقي الرماية",
        "ja": "バイアスロン解説：スキーと射撃の融合",
        "zh": "冬季两项解析：滑雪与射击的结合",
        "ko": "바이애슬론 설명: 스키와 사격의 만남"
    }'::jsonb,

    '{
        "en": "Discover how biathlon combines cross-country skiing with rifle shooting. Learn about the different race formats, shooting techniques, and what makes this sport so demanding.",
        "de": "Entdecken Sie, wie Biathlon Langlauf mit Gewehrschießen kombiniert. Erfahren Sie alles über Rennformate und Schießtechniken.",
        "fr": "Découvrez comment le biathlon combine ski de fond et tir à la carabine. Apprenez les formats de course et les techniques de tir.",
        "it": "Scopri come il biathlon combina sci di fondo e tiro con la carabina. Impara i formati di gara e le tecniche di tiro.",
        "es": "Descubre cómo el biatlón combina esquí de fondo con tiro con rifle. Aprende los formatos de carrera y técnicas de tiro.",
        "pt": "Descubra como o biatlo combina esqui cross-country com tiro de rifle. Aprenda os formatos de corrida e técnicas de tiro.",
        "nl": "Ontdek hoe biathlon langlaufen combineert met geweerschieten. Leer over de raceformaten en schiettechnieken.",
        "ar": "اكتشف كيف يجمع البياثلون بين التزلج الريفي والرماية بالبندقية. تعرف على أشكال السباق وتقنيات الرماية.",
        "ja": "バイアスロンがクロスカントリースキーとライフル射撃をどのように組み合わせているか発見してください。",
        "zh": "了解冬季两项如何将越野滑雪与步枪射击结合起来。学习比赛形式和射击技术。",
        "ko": "바이애슬론이 크로스컨트리 스키와 소총 사격을 어떻게 결합하는지 알아보세요."
    }'::jsonb,

    '{
        "en": "<p><strong>Biathlon</strong> is one of winter sports'' most unique challenges. Athletes must master two completely different skills: the endurance of cross-country skiing and the precision of rifle shooting.</p><h2>What is Biathlon?</h2><p>In biathlon, athletes ski cross-country courses with a small-bore rifle on their back. They stop at shooting ranges to hit targets, then continue skiing. Missed shots mean penalties - either extra skiing distance or time added.</p><p>The heart rate difference is extreme. During skiing, athletes'' hearts can beat 180+ times per minute. They must then calm themselves enough to shoot at targets just 4.5 centimeters wide from 50 meters away.</p><h2>Shooting: Prone vs Standing</h2><p><strong>Prone shooting</strong>: Athletes lie on the ground. This is more stable, with targets that are smaller (4.5cm diameter). Miss a shot, and you add penalty time or distance.</p><p><strong>Standing shooting</strong>: Athletes remain upright. The targets are larger (11.5cm) because standing is less stable. This requires incredible body control after skiing at full intensity.</p><h2>Race Formats</h2><h3>Sprint (7.5km women / 10km men)</h3><ul><li>Two shooting stages (prone + standing)</li><li>Each miss = 150m penalty loop</li><li>Fastest total time wins</li></ul><h3>Pursuit (10km women / 12.5km men)</h3><ul><li>Start order based on sprint results</li><li>Four shooting stages</li><li>First to cross finish line wins</li></ul><h3>Individual (15km women / 20km men)</h3><ul><li>Four shooting stages</li><li>Each miss = 1 minute added to time</li><li>Tests endurance and accuracy equally</li></ul><h3>Mass Start (12.5km women / 15km men)</h3><ul><li>Top 30 athletes start together</li><li>Four shooting stages</li><li>Exciting head-to-head racing</li></ul><h3>Relay (4x6km women / 4x7.5km men)</h3><ul><li>Teams of four</li><li>Three spare rounds per shooting stage</li><li>Penalty loop only after using all spares</li></ul><h2>Star Athletes</h2><p>Norway''s <strong>Johannes Thingnes Bø</strong> dominates men''s biathlon with incredible skiing speed and shooting accuracy. His brother <strong>Tarjei Bø</strong> is also a top competitor.</p><p>France''s <strong>Quentin Fillon Maillet</strong> and <strong>Emilien Jacquelin</strong> challenge Norwegian dominance, while Germany''s <strong>Benedikt Doll</strong> adds to the competition.</p><p>In women''s biathlon, Italy''s <strong>Lisa Vittozzi</strong> and <strong>Dorothea Wierer</strong> lead the charge, alongside France''s <strong>Justine Braisaz-Bouchet</strong> and Sweden''s <strong>Elvira Öberg</strong>.</p><h2>The IBU World Cup</h2><p>The <strong>IBU World Cup</strong> runs from November to March across venues in Europe. Athletes earn points based on race finishes, with the overall leader wearing the yellow bib.</p><p>Major venues include Ruhpolding (Germany), Antholz (Italy), and Oslo Holmenkollen (Norway).</p><h2>Watch on Neve26</h2><p>Follow all IBU World Cup races with real-time updates. Get notifications for your favorite biathletes and never miss the shooting drama.</p>",

        "de": "<p><strong>Biathlon</strong> ist eine der einzigartigsten Herausforderungen im Wintersport. Athleten müssen zwei völlig unterschiedliche Fähigkeiten beherrschen: die Ausdauer des Langlaufs und die Präzision des Gewehrschießens.</p><h2>Was ist Biathlon?</h2><p>Beim Biathlon laufen Athleten Langlaufstrecken mit einem Kleinkalibergewehr auf dem Rücken. Sie halten an Schießständen an, um Ziele zu treffen, und laufen dann weiter. Fehlschüsse bedeuten Strafen.</p><h2>Schießen: Liegend vs Stehend</h2><p><strong>Liegend schießen</strong>: Athleten liegen am Boden. Die Ziele sind 4,5cm im Durchmesser.</p><p><strong>Stehend schießen</strong>: Athleten bleiben aufrecht. Die Ziele sind größer (11,5cm), da Stehen weniger stabil ist.</p><h2>Rennformate</h2><h3>Sprint</h3><ul><li>Zwei Schießeinlagen</li><li>Jeder Fehler = 150m Strafrunde</li></ul><h3>Verfolgung</h3><ul><li>Startordnung basiert auf Sprint-Ergebnissen</li><li>Vier Schießeinlagen</li></ul><h3>Einzel</h3><ul><li>Vier Schießeinlagen</li><li>Jeder Fehler = 1 Minute Zeitstrafe</li></ul><h3>Massenstart</h3><ul><li>Top 30 Athleten starten zusammen</li><li>Vier Schießeinlagen</li></ul><h2>Star-Athleten</h2><p>Norwegens <strong>Johannes Thingnes Bø</strong> dominiert das Herren-Biathlon. Frankreichs <strong>Quentin Fillon Maillet</strong> und <strong>Emilien Jacquelin</strong> fordern die norwegische Dominanz heraus.</p><p>Im Damen-Biathlon führen Italiens <strong>Lisa Vittozzi</strong> und <strong>Dorothea Wierer</strong>.</p>",

        "fr": "<p>Le <strong>biathlon</strong> est l''un des défis les plus uniques des sports d''hiver. Les athlètes doivent maîtriser deux compétences complètement différentes : l''endurance du ski de fond et la précision du tir à la carabine.</p><h2>Qu''est-ce que le Biathlon?</h2><p>En biathlon, les athlètes skient sur des parcours de fond avec une carabine sur le dos. Ils s''arrêtent aux stands de tir pour atteindre des cibles, puis continuent à skier.</p><h2>Tir: Couché vs Debout</h2><p><strong>Tir couché</strong>: Les athlètes s''allongent au sol. C''est plus stable, avec des cibles de 4,5cm de diamètre.</p><p><strong>Tir debout</strong>: Les athlètes restent debout. Les cibles sont plus grandes (11,5cm) car la position debout est moins stable.</p><h2>Formats de Course</h2><h3>Sprint</h3><ul><li>Deux séances de tir</li><li>Chaque raté = boucle de pénalité de 150m</li></ul><h3>Poursuite</h3><ul><li>Ordre de départ basé sur les résultats du sprint</li><li>Quatre séances de tir</li></ul><h3>Individuel</h3><ul><li>Quatre séances de tir</li><li>Chaque raté = 1 minute ajoutée au temps</li></ul><h2>Athlètes Stars</h2><p>Le Norvégien <strong>Johannes Thingnes Bø</strong> domine le biathlon masculin. Les Français <strong>Quentin Fillon Maillet</strong> et <strong>Emilien Jacquelin</strong> défient la domination norvégienne.</p><p>En biathlon féminin, les Italiennes <strong>Lisa Vittozzi</strong> et <strong>Dorothea Wierer</strong> mènent la charge.</p>",

        "it": "<p>Il <strong>biathlon</strong> è una delle sfide più uniche degli sport invernali. Gli atleti devono padroneggiare due abilità completamente diverse: la resistenza dello sci di fondo e la precisione del tiro con la carabina.</p><h2>Cos''è il Biathlon?</h2><p>Nel biathlon, gli atleti sciano su percorsi di fondo con una carabina sulla schiena. Si fermano ai poligoni di tiro per colpire i bersagli, poi continuano a sciare.</p><h2>Tiro: Prono vs In Piedi</h2><p><strong>Tiro prono</strong>: Gli atleti si sdraiano a terra. I bersagli sono di 4,5cm di diametro.</p><p><strong>Tiro in piedi</strong>: Gli atleti rimangono in piedi. I bersagli sono più grandi (11,5cm) perché stare in piedi è meno stabile.</p><h2>Formati di Gara</h2><h3>Sprint</h3><ul><li>Due sessioni di tiro</li><li>Ogni errore = giro di penalità di 150m</li></ul><h3>Inseguimento</h3><ul><li>Ordine di partenza basato sui risultati dello sprint</li><li>Quattro sessioni di tiro</li></ul><h3>Individuale</h3><ul><li>Quattro sessioni di tiro</li><li>Ogni errore = 1 minuto aggiunto al tempo</li></ul><h2>Atleti Star</h2><p>Il norvegese <strong>Johannes Thingnes Bø</strong> domina il biathlon maschile. I francesi <strong>Quentin Fillon Maillet</strong> ed <strong>Emilien Jacquelin</strong> sfidano il dominio norvegese.</p><p>Nel biathlon femminile, le italiane <strong>Lisa Vittozzi</strong> e <strong>Dorothea Wierer</strong> guidano la carica.</p>",

        "es": "<p>El <strong>biatlón</strong> es uno de los desafíos más únicos de los deportes de invierno. Los atletas deben dominar dos habilidades completamente diferentes: la resistencia del esquí de fondo y la precisión del tiro con rifle.</p><h2>¿Qué es el Biatlón?</h2><p>En el biatlón, los atletas esquían en circuitos de fondo con un rifle en la espalda. Se detienen en los campos de tiro para acertar en los blancos, luego continúan esquiando.</p><h2>Tiro: Tendido vs De Pie</h2><p><strong>Tiro tendido</strong>: Los atletas se tumban en el suelo. Los blancos son de 4,5cm de diámetro.</p><p><strong>Tiro de pie</strong>: Los atletas permanecen de pie. Los blancos son más grandes (11,5cm) porque estar de pie es menos estable.</p><h2>Formatos de Carrera</h2><h3>Sprint</h3><ul><li>Dos series de tiro</li><li>Cada fallo = vuelta de penalización de 150m</li></ul><h3>Persecución</h3><ul><li>Orden de salida basado en resultados del sprint</li><li>Cuatro series de tiro</li></ul><h2>Atletas Estrella</h2><p>El noruego <strong>Johannes Thingnes Bø</strong> domina el biatlón masculino. Los franceses <strong>Quentin Fillon Maillet</strong> y <strong>Emilien Jacquelin</strong> desafían el dominio noruego.</p><p>En biatlón femenino, las italianas <strong>Lisa Vittozzi</strong> y <strong>Dorothea Wierer</strong> lideran.</p>",

        "pt": "<p>O <strong>biatlo</strong> é um dos desafios mais únicos dos esportes de inverno. Os atletas devem dominar duas habilidades completamente diferentes: a resistência do esqui cross-country e a precisão do tiro com rifle.</p><h2>O que é o Biatlo?</h2><p>No biatlo, os atletas esquiam em circuitos de cross-country com um rifle nas costas. Eles param nos campos de tiro para acertar alvos, depois continuam esquiando.</p><h2>Tiro: Deitado vs Em Pé</h2><p><strong>Tiro deitado</strong>: Os atletas se deitam no chão. Os alvos têm 4,5cm de diâmetro.</p><p><strong>Tiro em pé</strong>: Os atletas permanecem em pé. Os alvos são maiores (11,5cm) porque ficar em pé é menos estável.</p><h2>Formatos de Corrida</h2><h3>Sprint</h3><ul><li>Duas séries de tiro</li><li>Cada erro = volta de penalidade de 150m</li></ul><h3>Perseguição</h3><ul><li>Ordem de largada baseada nos resultados do sprint</li><li>Quatro séries de tiro</li></ul><h2>Atletas Estrelas</h2><p>O norueguês <strong>Johannes Thingnes Bø</strong> domina o biatlo masculino. Os franceses <strong>Quentin Fillon Maillet</strong> e <strong>Emilien Jacquelin</strong> desafiam o domínio norueguês.</p><p>No biatlo feminino, as italianas <strong>Lisa Vittozzi</strong> e <strong>Dorothea Wierer</strong> lideram.</p>",

        "nl": "<p><strong>Biathlon</strong> is een van de meest unieke uitdagingen in de wintersport. Atleten moeten twee compleet verschillende vaardigheden beheersen: het uithoudingsvermogen van langlaufen en de precisie van geweerschieten.</p><h2>Wat is Biathlon?</h2><p>Bij biathlon skiën atleten langlaufparcoursen met een geweer op hun rug. Ze stoppen bij schietbanen om doelen te raken, daarna gaan ze verder met skiën.</p><h2>Schieten: Liggend vs Staand</h2><p><strong>Liggend schieten</strong>: Atleten liggen op de grond. Doelen zijn 4,5cm diameter.</p><p><strong>Staand schieten</strong>: Atleten blijven rechtop staan. Doelen zijn groter (11,5cm) omdat staan minder stabiel is.</p><h2>Raceformaten</h2><h3>Sprint</h3><ul><li>Twee schietrondes</li><li>Elke misser = 150m strafronde</li></ul><h3>Achtervolging</h3><ul><li>Startvolgorde gebaseerd op sprintresultaten</li><li>Vier schietrondes</li></ul><h2>Sterathleten</h2><p>De Noor <strong>Johannes Thingnes Bø</strong> domineert het mannen biathlon. De Fransen <strong>Quentin Fillon Maillet</strong> en <strong>Emilien Jacquelin</strong> dagen de Noorse dominantie uit.</p><p>In het vrouwen biathlon leiden de Italianen <strong>Lisa Vittozzi</strong> en <strong>Dorothea Wierer</strong>.</p>",

        "ar": "<p><strong>البياثلون</strong> هو أحد أكثر التحديات فريدة في الرياضات الشتوية. يجب على الرياضيين إتقان مهارتين مختلفتين تماماً: قدرة التحمل في التزلج الريفي ودقة الرماية بالبندقية.</p><h2>ما هو البياثلون؟</h2><p>في البياثلون، يتزلج الرياضيون على مسارات ريفية مع بندقية على ظهورهم. يتوقفون عند ميادين الرماية لإصابة الأهداف، ثم يواصلون التزلج.</p><h2>الرماية: راقد مقابل واقف</h2><p><strong>الرماية راقداً</strong>: يستلقي الرياضيون على الأرض. قطر الأهداف 4.5 سم.</p><p><strong>الرماية واقفاً</strong>: يبقى الرياضيون منتصبين. الأهداف أكبر (11.5 سم) لأن الوقوف أقل استقراراً.</p><h2>أشكال السباق</h2><h3>سباق السرعة</h3><ul><li>جولتا رماية</li><li>كل خطأ = حلقة عقوبة 150م</li></ul><h3>المطاردة</h3><ul><li>ترتيب البداية يعتمد على نتائج سباق السرعة</li><li>أربع جولات رماية</li></ul><h2>الرياضيون النجوم</h2><p>يهيمن النرويجي <strong>يوهانس ثينجنس بو</strong> على بياثلون الرجال. يتحدى الفرنسيان <strong>كوينتين فيلون مايه</strong> و<strong>إميليان جاكلان</strong> الهيمنة النرويجية.</p><p>في بياثلون السيدات، تقود الإيطاليتان <strong>ليزا فيتوتزي</strong> و<strong>دوروثيا فيرر</strong>.</p>",

        "ja": "<p><strong>バイアスロン</strong>はウィンタースポーツで最もユニークな挑戦の一つです。選手はクロスカントリースキーの持久力とライフル射撃の精度という、全く異なる2つのスキルをマスターする必要があります。</p><h2>バイアスロンとは？</h2><p>バイアスロンでは、選手は小口径ライフルを背負ってクロスカントリーコースを滑ります。射撃場で的を撃ち、その後スキーを続けます。</p><h2>射撃：伏射 vs 立射</h2><p><strong>伏射</strong>：選手は地面に伏せます。的の直径は4.5cmです。</p><p><strong>立射</strong>：選手は立ったままです。立っている方が安定しないため、的は大きく（11.5cm）なっています。</p><h2>レース形式</h2><h3>スプリント</h3><ul><li>2回の射撃ステージ</li><li>各ミス = 150mペナルティループ</li></ul><h3>パシュート</h3><ul><li>スタート順はスプリント結果に基づく</li><li>4回の射撃ステージ</li></ul><h2>スター選手</h2><p>ノルウェーの<strong>ヨハネス・ティンネス・ボー</strong>が男子バイアスロンを支配しています。フランスの<strong>カンタン・フィヨン・マイエ</strong>と<strong>エミリアン・ジャクラン</strong>がノルウェーの支配に挑んでいます。</p><p>女子バイアスロンでは、イタリアの<strong>リサ・ヴィットッツィ</strong>と<strong>ドロテア・ヴィーラー</strong>がリードしています。</p>",

        "zh": "<p><strong>冬季两项</strong>是冬季运动中最独特的挑战之一。运动员必须掌握两种完全不同的技能：越野滑雪的耐力和步枪射击的精准度。</p><h2>什么是冬季两项？</h2><p>在冬季两项中，运动员背着小口径步枪在越野滑雪赛道上滑行。他们在射击场停下来击中目标，然后继续滑雪。</p><h2>射击：卧射 vs 立射</h2><p><strong>卧射</strong>：运动员趴在地上。目标直径4.5厘米。</p><p><strong>立射</strong>：运动员保持站立。由于站立不太稳定，目标更大（11.5厘米）。</p><h2>比赛形式</h2><h3>短距离</h3><ul><li>两个射击环节</li><li>每次脱靶 = 150米惩罚圈</li></ul><h3>追逐</h3><ul><li>起跑顺序基于短距离成绩</li><li>四个射击环节</li></ul><h2>明星运动员</h2><p>挪威的<strong>约翰内斯·廷内斯·伯</strong>统治着男子冬季两项。法国的<strong>坎廷·菲永·迈耶</strong>和<strong>埃米利安·雅克兰</strong>挑战挪威的统治地位。</p><p>在女子冬季两项中，意大利的<strong>丽莎·维托齐</strong>和<strong>多罗特亚·维雷尔</strong>领跑。</p>",

        "ko": "<p><strong>바이애슬론</strong>은 겨울 스포츠에서 가장 독특한 도전 중 하나입니다. 선수들은 크로스컨트리 스키의 지구력과 소총 사격의 정밀함이라는 완전히 다른 두 가지 기술을 마스터해야 합니다.</p><h2>바이애슬론이란?</h2><p>바이애슬론에서 선수들은 소구경 소총을 등에 메고 크로스컨트리 코스를 스킵니다. 사격장에서 멈춰 표적을 맞추고 다시 스키를 탑니다.</p><h2>사격: 엎드려 쏴 vs 서서 쏴</h2><p><strong>엎드려 사격</strong>: 선수들이 땅에 엎드립니다. 표적 직경은 4.5cm입니다.</p><p><strong>서서 사격</strong>: 선수들이 서서 쏩니다. 서 있는 것이 덜 안정적이므로 표적이 더 큽니다(11.5cm).</p><h2>경기 형식</h2><h3>스프린트</h3><ul><li>두 번의 사격 스테이지</li><li>각 실수 = 150m 페널티 루프</li></ul><h3>추적</h3><ul><li>출발 순서는 스프린트 결과에 기반</li><li>네 번의 사격 스테이지</li></ul><h2>스타 선수</h2><p>노르웨이의 <strong>요하네스 팅네스 뵈</strong>가 남자 바이애슬론을 지배하고 있습니다. 프랑스의 <strong>캉탱 피용 마예</strong>와 <strong>에밀리앙 자클랭</strong>이 노르웨이의 지배에 도전하고 있습니다.</p><p>여자 바이애슬론에서는 이탈리아의 <strong>리사 비토치</strong>와 <strong>도로테아 비에레르</strong>가 선두를 달리고 있습니다.</p>"
    }'::jsonb,

    'sport-explainer',
    'BTH',

    '{
        "en": "Learn how biathlon works. Discover the combination of cross-country skiing and rifle shooting, race formats, and top athletes in this complete guide.",
        "de": "Erfahren Sie, wie Biathlon funktioniert. Entdecken Sie die Kombination aus Langlauf und Gewehrschießen, Rennformate und Top-Athleten.",
        "fr": "Apprenez comment fonctionne le biathlon. Découvrez la combinaison du ski de fond et du tir à la carabine, les formats de course et les meilleurs athlètes.",
        "it": "Scopri come funziona il biathlon. La combinazione di sci di fondo e tiro con carabina, i formati di gara e i migliori atleti.",
        "es": "Aprende cómo funciona el biatlón. Descubre la combinación de esquí de fondo y tiro con rifle, formatos de carrera y mejores atletas.",
        "pt": "Aprenda como funciona o biatlo. Descubra a combinação de esqui cross-country e tiro com rifle, formatos de corrida e melhores atletas.",
        "nl": "Leer hoe biathlon werkt. Ontdek de combinatie van langlaufen en geweerschieten, raceformaten en topathleten.",
        "ar": "تعلم كيف يعمل البياثلون. اكتشف الجمع بين التزلج الريفي والرماية بالبندقية وأشكال السباق وأفضل الرياضيين.",
        "ja": "バイアスロンの仕組みを学びましょう。クロスカントリースキーとライフル射撃の組み合わせ、レース形式、トップ選手を解説。",
        "zh": "了解冬季两项的运作方式。探索越野滑雪与步枪射击的结合、比赛形式和顶级运动员。",
        "ko": "바이애슬론의 작동 방식을 알아보세요. 크로스컨트리 스키와 소총 사격의 결합, 경기 형식, 최고의 선수들을 소개합니다."
    }'::jsonb,

    'published',
    NOW(),
    'manual'
);

