INSERT INTO articles (
    slug, title, excerpt, content, category, sport_code,
    meta_description, status, published_at, source_type
) VALUES (
    'curling-strategy-rules-guide',

    '{
        "en": "Curling Strategy and Rules Guide",
        "de": "Curling: Strategie und Regeln erklärt",
        "fr": "Guide des Stratégies et Règles du Curling",
        "it": "Guida a Strategie e Regole del Curling",
        "es": "Guía de Estrategia y Reglas del Curling",
        "pt": "Guia de Estratégia e Regras do Curling",
        "nl": "Curling: Strategie en Regels Gids",
        "ar": "دليل استراتيجية وقواعد الكيرلنج",
        "ja": "カーリング戦略とルール完全ガイド",
        "zh": "冰壶策略与规则指南",
        "ko": "컬링 전략과 규칙 가이드"
    }'::jsonb,

    '{
        "en": "Master the game of curling. Learn the rules, understand strategy concepts like the hammer, and discover why this sport is called chess on ice.",
        "de": "Meistern Sie das Curling-Spiel. Lernen Sie die Regeln, verstehen Sie Strategiekonzepte und entdecken Sie, warum dieser Sport Schach auf Eis genannt wird.",
        "fr": "Maîtrisez le curling. Apprenez les règles, comprenez les concepts stratégiques et découvrez pourquoi ce sport est appelé échecs sur glace.",
        "it": "Padroneggia il curling. Impara le regole, comprendi i concetti strategici e scopri perché questo sport è chiamato scacchi sul ghiaccio.",
        "es": "Domina el curling. Aprende las reglas, comprende los conceptos estratégicos y descubre por qué este deporte se llama ajedrez sobre hielo.",
        "pt": "Domine o curling. Aprenda as regras, entenda os conceitos estratégicos e descubra por que este esporte é chamado de xadrez no gelo.",
        "nl": "Beheers curling. Leer de regels, begrijp strategische concepten en ontdek waarom deze sport schaak op ijs wordt genoemd.",
        "ar": "أتقن لعبة الكيرلنج. تعلم القواعد وافهم مفاهيم الاستراتيجية واكتشف لماذا تسمى هذه الرياضة شطرنج على الجليد.",
        "ja": "カーリングをマスターしよう。ルールを学び、戦略概念を理解し、なぜこのスポーツが氷上のチェスと呼ばれるか発見しましょう。",
        "zh": "掌握冰壶运动。学习规则，理解策略概念，了解为什么这项运动被称为冰上象棋。",
        "ko": "컬링을 마스터하세요. 규칙을 배우고 전략 개념을 이해하며 왜 이 스포츠가 얼음 위의 체스라고 불리는지 알아보세요."
    }'::jsonb,

    '{
        "en": "<p><strong>Curling</strong> is often called \"chess on ice\" - and for good reason. This strategic sport combines physical skill with tactical thinking, making every shot a calculated decision.</p><h2>The Basics</h2><p>Two teams of four players take turns sliding heavy granite stones (weighing about 20kg) across a sheet of ice toward a target called the \"house.\" The goal is to get your stones closer to the center (the \"button\") than your opponent''s stones.</p><h2>The Team</h2><ul><li><strong>Lead</strong>: Throws the first two stones</li><li><strong>Second</strong>: Throws stones 3 and 4</li><li><strong>Third (Vice-Skip)</strong>: Throws stones 5 and 6, helps with strategy</li><li><strong>Skip</strong>: Team captain, throws last two stones, calls the shots</li></ul><h2>Scoring</h2><p>Only one team scores per end (round). The team with the stone closest to the button scores one point for each of their stones that is closer than the opponent''s closest stone.</p><p>If red has two stones closer than blue''s closest stone, red scores 2 points.</p><h2>The Hammer Advantage</h2><p>The team that throws last in an end has the <strong>hammer</strong>. This is a significant advantage - the skip can see exactly where all other stones are before throwing their final stone.</p><p>If you score, you lose the hammer. Many teams prefer to score at least two points with the hammer; scoring only one (\"forcing\") gives the hammer to the opponent.</p><h2>Key Strategy Concepts</h2><h3>Guards</h3><p>Stones placed in front of the house to protect scoring stones. The \"free guard zone\" rule means guards cannot be removed until the fifth stone of each end.</p><h3>Draws</h3><p>Shots intended to stop in the house, ideally close to the button.</p><h3>Takeouts</h3><p>Shots that remove opponent''s stones from play.</p><h3>Freezes</h3><p>Drawing your stone to rest directly against an opponent''s stone, making it hard to remove.</p><h2>Sweeping</h2><p>Team members sweep the ice in front of moving stones. This:</p><ul><li>Makes the stone travel farther</li><li>Makes the stone curl less</li></ul><p>The skip calls sweeping instructions based on how the stone is tracking.</p><h2>Standard Game</h2><p>Most competitive games are 10 ends. Each end takes about 15 minutes. Teams can also concede if the score difference becomes too large.</p><h2>Watch on Neve26</h2><p>Follow curling events with our schedule tracker. The strategic depth makes every end exciting!</p>",

        "de": "<p><strong>Curling</strong> wird oft \"Schach auf Eis\" genannt - und das aus gutem Grund. Dieser strategische Sport kombiniert körperliches Geschick mit taktischem Denken.</p><h2>Die Grundlagen</h2><p>Zwei Teams mit je vier Spielern schieben abwechselnd schwere Granitsteine (etwa 20kg) über eine Eisbahn auf ein Ziel namens \"Haus\". Das Ziel ist es, Ihre Steine näher an die Mitte (den \"Button\") zu bringen als die Steine des Gegners.</p><h2>Das Team</h2><ul><li><strong>Lead</strong>: Wirft die ersten zwei Steine</li><li><strong>Second</strong>: Wirft Steine 3 und 4</li><li><strong>Third (Vice-Skip)</strong>: Wirft Steine 5 und 6</li><li><strong>Skip</strong>: Teamkapitän, wirft die letzten zwei Steine</li></ul><h2>Punktestand</h2><p>Nur ein Team punktet pro End. Das Team mit dem Stein am nächsten zum Button erhält einen Punkt für jeden ihrer Steine, der näher ist als der nächste Stein des Gegners.</p><h2>Der Hammer-Vorteil</h2><p>Das Team, das als letztes in einem End wirft, hat den <strong>Hammer</strong>. Dies ist ein bedeutender Vorteil.</p><h2>Wichtige Strategiekonzepte</h2><h3>Guards</h3><p>Steine vor dem Haus platziert, um punktende Steine zu schützen.</p><h3>Draws</h3><p>Schüsse, die im Haus landen sollen.</p><h3>Takeouts</h3><p>Schüsse, die gegnerische Steine entfernen.</p><h2>Wischen</h2><p>Teammitglieder wischen das Eis vor bewegenden Steinen. Dies macht den Stein weiter reisen und weniger curlen.</p>",

        "fr": "<p>Le <strong>curling</strong> est souvent appelé \"échecs sur glace\" - et pour cause. Ce sport stratégique combine habileté physique et réflexion tactique.</p><h2>Les Bases</h2><p>Deux équipes de quatre joueurs font glisser à tour de rôle des pierres de granit lourdes (environ 20kg) sur une piste de glace vers une cible appelée la \"maison\".</p><h2>L''Équipe</h2><ul><li><strong>Lead</strong>: Lance les deux premières pierres</li><li><strong>Second</strong>: Lance les pierres 3 et 4</li><li><strong>Third (Vice-Skip)</strong>: Lance les pierres 5 et 6</li><li><strong>Skip</strong>: Capitaine de l''équipe, lance les deux dernières pierres</li></ul><h2>Pointage</h2><p>Une seule équipe marque par manche. L''équipe avec la pierre la plus proche du bouton marque un point pour chaque pierre plus proche que la pierre la plus proche de l''adversaire.</p><h2>L''Avantage du Marteau</h2><p>L''équipe qui lance en dernier dans une manche a le <strong>marteau</strong>. C''est un avantage significatif.</p><h2>Concepts Stratégiques Clés</h2><h3>Gardes</h3><p>Pierres placées devant la maison pour protéger les pierres marquantes.</p><h3>Tirés</h3><p>Tirs destinés à s''arrêter dans la maison.</p><h3>Sorties</h3><p>Tirs qui retirent les pierres de l''adversaire.</p><h2>Balayage</h2><p>Les membres de l''équipe balaient la glace devant les pierres en mouvement. Cela fait voyager la pierre plus loin et moins courber.</p>",

        "it": "<p>Il <strong>curling</strong> è spesso chiamato \"scacchi sul ghiaccio\" - e per una buona ragione. Questo sport strategico combina abilità fisica e pensiero tattico.</p><h2>Le Basi</h2><p>Due squadre di quattro giocatori fanno scivolare a turno pesanti pietre di granito (circa 20kg) su una pista di ghiaccio verso un bersaglio chiamato la \"casa\".</p><h2>La Squadra</h2><ul><li><strong>Lead</strong>: Lancia le prime due pietre</li><li><strong>Second</strong>: Lancia le pietre 3 e 4</li><li><strong>Third (Vice-Skip)</strong>: Lancia le pietre 5 e 6</li><li><strong>Skip</strong>: Capitano della squadra, lancia le ultime due pietre</li></ul><h2>Punteggio</h2><p>Solo una squadra segna per end. La squadra con la pietra più vicina al bottone segna un punto per ogni pietra più vicina della pietra più vicina dell''avversario.</p><h2>Il Vantaggio del Martello</h2><p>La squadra che lancia per ultima in un end ha il <strong>martello</strong>. Questo è un vantaggio significativo.</p><h2>Concetti Strategici Chiave</h2><h3>Guard</h3><p>Pietre piazzate davanti alla casa per proteggere le pietre che segnano.</p><h3>Draw</h3><p>Tiri destinati a fermarsi nella casa.</p><h3>Takeout</h3><p>Tiri che rimuovono le pietre dell''avversario.</p><h2>Spazzolata</h2><p>I membri della squadra spazzolano il ghiaccio davanti alle pietre in movimento. Questo fa viaggiare la pietra più lontano e curvare meno.</p>",

        "es": "<p>El <strong>curling</strong> a menudo se llama \"ajedrez sobre hielo\" - y con razón. Este deporte estratégico combina habilidad física con pensamiento táctico.</p><h2>Los Básicos</h2><p>Dos equipos de cuatro jugadores turnan para deslizar piedras pesadas de granito (unos 20kg) por una pista de hielo hacia un objetivo llamado la \"casa\".</p><h2>El Equipo</h2><ul><li><strong>Lead</strong>: Lanza las primeras dos piedras</li><li><strong>Second</strong>: Lanza las piedras 3 y 4</li><li><strong>Third (Vice-Skip)</strong>: Lanza las piedras 5 y 6</li><li><strong>Skip</strong>: Capitán del equipo, lanza las últimas dos piedras</li></ul><h2>Puntuación</h2><p>Solo un equipo puntúa por end. El equipo con la piedra más cercana al botón anota un punto por cada piedra más cercana que la piedra más cercana del oponente.</p><h2>La Ventaja del Martillo</h2><p>El equipo que lanza último en un end tiene el <strong>martillo</strong>. Esta es una ventaja significativa.</p><h2>Conceptos Estratégicos Clave</h2><h3>Guardas</h3><p>Piedras colocadas frente a la casa para proteger las piedras que puntúan.</p><h3>Draws</h3><p>Tiros destinados a detenerse en la casa.</p><h3>Takeouts</h3><p>Tiros que eliminan las piedras del oponente.</p><h2>Barrido</h2><p>Los miembros del equipo barren el hielo frente a las piedras en movimiento. Esto hace que la piedra viaje más lejos y curve menos.</p>",

        "pt": "<p>O <strong>curling</strong> é frequentemente chamado de \"xadrez no gelo\" - e com razão. Este esporte estratégico combina habilidade física com pensamento tático.</p><h2>O Básico</h2><p>Duas equipes de quatro jogadores se revezam deslizando pedras pesadas de granito (cerca de 20kg) através de uma pista de gelo em direção a um alvo chamado \"casa\".</p><h2>A Equipe</h2><ul><li><strong>Lead</strong>: Lança as duas primeiras pedras</li><li><strong>Second</strong>: Lança as pedras 3 e 4</li><li><strong>Third (Vice-Skip)</strong>: Lança as pedras 5 e 6</li><li><strong>Skip</strong>: Capitão da equipe, lança as duas últimas pedras</li></ul><h2>Pontuação</h2><p>Apenas uma equipe pontua por end. A equipe com a pedra mais próxima do botão marca um ponto para cada pedra mais próxima do que a pedra mais próxima do oponente.</p><h2>A Vantagem do Martelo</h2><p>A equipe que lança por último em um end tem o <strong>martelo</strong>. Esta é uma vantagem significativa.</p><h2>Conceitos Estratégicos Chave</h2><h3>Guardas</h3><p>Pedras colocadas na frente da casa para proteger as pedras que pontuam.</p><h3>Draws</h3><p>Arremessos destinados a parar na casa.</p><h3>Takeouts</h3><p>Arremessos que removem as pedras do oponente.</p><h2>Varrer</h2><p>Os membros da equipe varrem o gelo na frente das pedras em movimento. Isso faz a pedra viajar mais longe e curvar menos.</p>",

        "nl": "<p><strong>Curling</strong> wordt vaak \"schaak op ijs\" genoemd - en met goede reden. Deze strategische sport combineert fysieke vaardigheid met tactisch denken.</p><h2>De Basis</h2><p>Twee teams van vier spelers schuiven om de beurt zware granieten stenen (ongeveer 20kg) over een ijsbaan naar een doel genaamd het \"huis\".</p><h2>Het Team</h2><ul><li><strong>Lead</strong>: Gooit de eerste twee stenen</li><li><strong>Second</strong>: Gooit stenen 3 en 4</li><li><strong>Third (Vice-Skip)</strong>: Gooit stenen 5 en 6</li><li><strong>Skip</strong>: Teamkapitein, gooit de laatste twee stenen</li></ul><h2>Scoren</h2><p>Slechts één team scoort per end. Het team met de steen het dichtst bij de button scoort één punt voor elke steen die dichterbij is dan de dichtstbijzijnde steen van de tegenstander.</p><h2>Het Hamer Voordeel</h2><p>Het team dat als laatste gooit in een end heeft de <strong>hamer</strong>. Dit is een significant voordeel.</p><h2>Belangrijke Strategische Concepten</h2><h3>Guards</h3><p>Stenen geplaatst voor het huis om scorende stenen te beschermen.</p><h3>Draws</h3><p>Schoten bedoeld om in het huis te stoppen.</p><h3>Takeouts</h3><p>Schoten die stenen van de tegenstander verwijderen.</p><h2>Vegen</h2><p>Teamleden vegen het ijs voor bewegende stenen. Dit maakt dat de steen verder reist en minder krult.</p>",

        "ar": "<p>غالباً ما يُطلق على <strong>الكيرلنج</strong> \"شطرنج على الجليد\" - وهذا لسبب وجيه. تجمع هذه الرياضة الاستراتيجية بين المهارة البدنية والتفكير التكتيكي.</p><h2>الأساسيات</h2><p>يتناوب فريقان من أربعة لاعبين على تمرير أحجار جرانيتية ثقيلة (حوالي 20 كجم) عبر ملعب جليدي نحو هدف يسمى \"البيت\".</p><h2>الفريق</h2><ul><li><strong>القائد</strong>: يرمي الحجرين الأولين</li><li><strong>الثاني</strong>: يرمي الحجرين 3 و4</li><li><strong>الثالث (نائب السكيب)</strong>: يرمي الحجرين 5 و6</li><li><strong>السكيب</strong>: قائد الفريق، يرمي آخر حجرين</li></ul><h2>التسجيل</h2><p>فريق واحد فقط يسجل في كل جولة. الفريق صاحب الحجر الأقرب للزر يحصل على نقطة لكل حجر أقرب من أقرب حجر للخصم.</p><h2>ميزة المطرقة</h2><p>الفريق الذي يرمي أخيراً في الجولة لديه <strong>المطرقة</strong>. هذه ميزة كبيرة.</p><h2>مفاهيم استراتيجية رئيسية</h2><h3>الحراس</h3><p>أحجار توضع أمام البيت لحماية الأحجار المسجلة.</p><h3>السحب</h3><p>رميات تهدف للتوقف في البيت.</p><h3>الإخراج</h3><p>رميات تزيل أحجار الخصم.</p><h2>الكنس</h2><p>يكنس أعضاء الفريق الجليد أمام الأحجار المتحركة. هذا يجعل الحجر يسافر أبعد وينحني أقل.</p>",

        "ja": "<p><strong>カーリング</strong>はしばしば「氷上のチェス」と呼ばれます - それには理由があります。この戦略的なスポーツは、身体的なスキルと戦術的思考を組み合わせています。</p><h2>基本</h2><p>4人の選手で構成される2チームが交互に、重い花崗岩のストーン（約20kg）を氷の上を滑らせて「ハウス」と呼ばれるターゲットに向けます。</p><h2>チーム</h2><ul><li><strong>リード</strong>：最初の2投を投げる</li><li><strong>セカンド</strong>：3投目と4投目を投げる</li><li><strong>サード（バイススキップ）</strong>：5投目と6投目を投げる</li><li><strong>スキップ</strong>：チームキャプテン、最後の2投を投げる</li></ul><h2>スコアリング</h2><p>各エンドで得点できるのは1チームのみ。ボタンに最も近いストーンを持つチームが、相手の最も近いストーンより近い自チームのストーン1つにつき1点を獲得します。</p><h2>ハンマーの優位性</h2><p>エンドで最後に投げるチームが<strong>ハンマー</strong>を持ちます。これは大きな優位性です。</p><h2>主要な戦略概念</h2><h3>ガード</h3><p>得点ストーンを守るためにハウスの前に置かれたストーン。</p><h3>ドロー</h3><p>ハウス内に止めることを意図したショット。</p><h3>テイクアウト</h3><p>相手のストーンを取り除くショット。</p><h2>スイーピング</h2><p>チームメンバーが動いているストーンの前の氷を掃きます。これによりストーンはより遠くまで進み、曲がりが少なくなります。</p>",

        "zh": "<p><strong>冰壶</strong>常被称为"冰上象棋"——这是有充分理由的。这项战略性运动将身体技能与战术思维相结合。</p><h2>基础知识</h2><p>两支四人队伍轮流将重约20公斤的花岗岩壶滑向一个叫做"大本营"的目标。</p><h2>队伍</h2><ul><li><strong>一垒</strong>：投掷前两个壶</li><li><strong>二垒</strong>：投掷第3和第4个壶</li><li><strong>三垒（副队长）</strong>：投掷第5和第6个壶</li><li><strong>队长</strong>：队长，投掷最后两个壶</li></ul><h2>计分</h2><p>每局只有一队得分。拥有最接近圆心的壶的队伍，其每个比对手最近的壶更接近圆心的壶可得一分。</p><h2>后手优势</h2><p>在一局中最后投掷的队伍拥有<strong>后手</strong>。这是一个显著的优势。</p><h2>关键战略概念</h2><h3>保护壶</h3><p>放置在大本营前面保护得分壶的壶。</p><h3>进营</h3><p>旨在停在大本营内的投掷。</p><h3>击打</h3><p>移除对手壶的投掷。</p><h2>擦冰</h2><p>队员在移动的壶前擦冰。这使壶走得更远，弯曲更少。</p>",

        "ko": "<p><strong>컬링</strong>은 종종 \"얼음 위의 체스\"라고 불립니다 - 그럴 만한 이유가 있습니다. 이 전략적인 스포츠는 신체적 기술과 전술적 사고를 결합합니다.</p><h2>기본</h2><p>4명으로 구성된 두 팀이 번갈아 무거운 화강암 스톤(약 20kg)을 얼음 위로 밀어 \"하우스\"라고 불리는 목표 지점을 향해 보냅니다.</p><h2>팀</h2><ul><li><strong>리드</strong>: 처음 두 개의 스톤을 던짐</li><li><strong>세컨드</strong>: 3번째와 4번째 스톤을 던짐</li><li><strong>서드 (바이스 스킵)</strong>: 5번째와 6번째 스톤을 던짐</li><li><strong>스킵</strong>: 팀 주장, 마지막 두 개의 스톤을 던짐</li></ul><h2>득점</h2><p>엔드당 한 팀만 득점합니다. 버튼에 가장 가까운 스톤을 가진 팀이 상대방의 가장 가까운 스톤보다 더 가까운 자신의 스톤 수만큼 점수를 얻습니다.</p><h2>해머 어드밴티지</h2><p>엔드에서 마지막으로 던지는 팀이 <strong>해머</strong>를 가집니다. 이것은 상당한 이점입니다.</p><h2>주요 전략 개념</h2><h3>가드</h3><p>득점 스톤을 보호하기 위해 하우스 앞에 놓인 스톤.</p><h3>드로</h3><p>하우스 안에 멈추도록 의도된 샷.</p><h3>테이크아웃</h3><p>상대방의 스톤을 제거하는 샷.</p><h2>스위핑</h2><p>팀원들이 움직이는 스톤 앞의 얼음을 쓸어냅니다. 이렇게 하면 스톤이 더 멀리 가고 덜 휘어집니다.</p>"
    }'::jsonb,

    'sport-explainer',
    'CUR',

    '{
        "en": "Complete guide to curling rules and strategy. Learn about the hammer, sweeping, scoring, and why curling is called chess on ice.",
        "de": "Kompletter Leitfaden zu Curling-Regeln und Strategie. Erfahren Sie alles über Hammer, Wischen, Punktestand und Schach auf Eis.",
        "fr": "Guide complet des règles et stratégies du curling. Découvrez le marteau, le balayage, le pointage et les échecs sur glace.",
        "it": "Guida completa a regole e strategia del curling. Scopri il martello, la spazzolata, il punteggio e gli scacchi sul ghiaccio.",
        "es": "Guía completa de reglas y estrategia del curling. Aprende sobre el martillo, barrido, puntuación y ajedrez sobre hielo.",
        "pt": "Guia completo de regras e estratégia do curling. Aprenda sobre o martelo, varredura, pontuação e xadrez no gelo.",
        "nl": "Complete gids voor curling regels en strategie. Leer over de hamer, vegen, scoren en schaak op ijs.",
        "ar": "دليل شامل لقواعد واستراتيجية الكيرلنج. تعرف على المطرقة والكنس والتسجيل والشطرنج على الجليد.",
        "ja": "カーリングのルールと戦略完全ガイド。ハンマー、スイーピング、スコアリング、氷上のチェスについて学びましょう。",
        "zh": "冰壶规则和策略完全指南。了解后手、擦冰、计分以及冰上象棋的由来。",
        "ko": "컬링 규칙과 전략 완벽 가이드. 해머, 스위핑, 득점, 그리고 왜 컬링이 얼음 위의 체스라고 불리는지 알아보세요."
    }'::jsonb,

    'published',
